import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 numCalls, uint256 fuzzSeed) public {
        // Bound to ensure we test with multiple calls but keep execution reasonable
        numCalls = uint8(bound(numCalls, 1, 20));

        uint256 expectedPot = 0;
        uint256 wins = 0;

        for (uint8 i = 0; i < numCalls; i++) {
            // Derive pseudo-randomness from fuzzSeed and iteration
            uint256 randomResult = uint256(keccak256(abi.encode(fuzzSeed, i))) % 2;

            // Fund a fresh player for each call
            address player = address(uint160(uint256(keccak256(abi.encode(fuzzSeed, i, 1)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();

            if (randomResult == 0) {
                wins++;
            }
        }

        // The reference contract's pot should be 0 if at least one win occurred,
        // because pot is reset to 0 after each win and never accumulates beyond a single loss round.
        // The buggy version fails to reset pot, so after any win, pot will be > 0.
        if (wins > 0) {
            assertTrue(c.pot() == 0);
        } else {
            // If no wins, pot accumulates with each call
            assertTrue(c.pot() == uint256(numCalls) * 10);
        }
    }
}

