pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 rand, uint256 extra) public {
        // 1. admissible domain: msg.value == TICKET_AMOUNT (10 wei)
        uint constant TICKET_AMOUNT = 10;
        address player = address(0x1234);
        vm.deal(player, TICKET_AMOUNT);
        // 2. ensure randomness yields a win (random == 0) for the fuzzed input
        //    block.timestamp and block.difficulty control the hash; we set them so that
        //    uint(keccak256(...)) % 2 == 0. We can only do this by warping/rolling to
        //    values that make the hash even.
        //    Since the fuzzer provides rand and extra, we construct block.timestamp and
        //    block.difficulty such that the hash parity is 0.
        //    We ensure: uint(keccak256(abi.encodePacked(ts, diff))) % 2 == 0
        //    To keep domain wide, we let the fuzzer pick rand (0-255) and extra (uint256),
        //    then set timestamp = rand, difficulty = extra, and warp to a favorable ts/diff
        //    pair by tweaking timestamp until parity is 0.
        uint ts = uint(rand) & 0xFF;
        uint diff = extra;
        vm.warp(ts);
        vm.roll(diff);
        // If the parity is 1, increment ts until it's 0 (keep domain wide)
        while (uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 != 0) {
            // bound fallback: just bump timestamp
            ts++;
            vm.warp(ts);
        }
        // 3. drive c
        vm.prank(player);
        c.play{value: TICKET_AMOUNT}();
        // 4. assertion: after a win, pot must be zero
        assertTrue(c.pot() == 0);
    }
}

