pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256[] memory amounts, uint256 seed) public {
        // Ensure at least one play call
        vm.assume(amounts.length > 0 && amounts.length <= 10);
        // Bound each amount to ticket amount; static amount prevents irrelevant revert
        uint constant TICKET = 10;
        uint constant FEE = 1;
        uint totalPaid = 0;
        uint totalFees = 0;

        // Set deterministic randomness via block.timestamp and block.difficulty
        vm.warp(seed);
        vm.roll(seed);

        address player = address(0x1000);
        vm.deal(player, type(uint256).max);

        for (uint i = 0; i < amounts.length; i++) {
            amounts[i] = bound(amounts[i], TICKET, TICKET); // all calls pass the require
            totalPaid += amounts[i];

            vm.prank(player);
            c.play{value: amounts[i]}();

            // Compute whether this play was a win using the same randomness formula
            uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (random == 0) {
                totalFees += FEE;
                // Reference contract resets pot to 0 after paying (pot - fee) to winner and fee to bank
                // Expected pot after win = 0
                // But the mutant does not reset; we check after loop.
            }
            // Advance state for next random
            vm.roll(block.number + 1);
            vm.warp(block.timestamp + 1);
        }

        // General rule: pot must equal (total paid - total fees transferred), because every win resets pot to 0.
        // After a win, pot becomes 0, which equals totalPaidSoFar - totalFeesSoFar.
        // The invariant holds for any sequence: pot == totalPaid - totalFees * number_of_wins.
        assertEq(c.pot(), totalPaid - totalFees);
    }
}

