contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 random_override) public {
        // Widen domain: random_override can be 0 or 1 via vm.roll modulo 2
        vm.roll(random_override); // affects block.difficulty when ==0, but we also warp to influence
        vm.warp(random_override); // ensure different timestamps, timestamp used in keccak256
        address player = address(0x1234);
        vm.deal(player, 10 ether);
        uint256 preBank = address(c.bank()).balance;
        uint256 prePot = c.pot();
        uint256 preBal = address(c).balance;
        vm.prank(player);
        try c.play{value: 10}() {} catch {}
        uint256 postBal = address(c).balance;
        uint256 postPot = c.pot();
        uint256 bankDelta = address(c.bank()).balance - preBank;
        // Reference invariant: if bank received its fee (1 wei), pot must equal address(c).balance - 1.
        // Otherwise, pot must equal address(c).balance (i.e., no win or callback failure, so pot unchanged).
        if (bankDelta == 1) {
            assertTrue(postPot == postBal - 1);
        } else {
            assertTrue(postPot == postBal);
        }
    }
}

